// Validate Salesforce HMAC signature
const crypto = require('crypto');
const secret = $env.SF_WEBHOOK_SECRET;
const sig = $input.first().json.headers?.['x-salesforce-signature'] || '';
const rawBody = JSON.stringify($input.first().json.body);

if (secret) {
  const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
  const provided = sig.replace(/^sha256=/, '');
  let valid = false;
  try {
    valid = crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(provided || '0'.repeat(64), 'hex'));
  } catch { valid = false; }
  if (!valid) {
    throw new Error('Invalid Salesforce webhook signature');
  }
}

// Pass through the body
return [{ json: $input.first().json.body }];
